// tb_merkle.v — checks merkle_builder against fpga/vectors/tree_kat.txt (generated by
// gen_tree_kat.cpp from blocks/hash/hash.h's vertex()). Lines:
//   S <domain:08x> <start: 8 u32>   the tree start
//   L <n> <n digests x 8 u32>       the leaves
//   V <n> <n digests x 8 u32>       per level (checked against the builder's RAM)
//   R <root: 8 u32>                 the expected root
`timescale 1ns/1ps
module tb;
  reg clk = 0, rst_n = 0, load_en = 0, start = 0;
  reg [31:0] load_addr;
  reg [255:0] load_data, startw;
  wire busy, done;
  wire [255:0] root;
  reg [31:0] w;
  reg [7:0] ch;
  reg [1023:0] discard;
  integer fh, sc, i, j, nlev, got, eof = 0, status = 2;

  merkle_builder #(.NLEAF_LOG2(3)) dut (
      .clk(clk), .rst_n(rst_n), .load_en(load_en), .load_addr(load_addr),
      .load_data(load_data), .startw(startw), .start(start),
      .busy(busy), .done(done), .root(root));
  always #5 clk = ~clk;

  task read_digest;                     // 8 u32 into load_data
    integer t;
    begin
      for (t = 0; t < 8; t = t + 1) begin
        sc = $fscanf(fh, "%h", w);
        load_data[32*t +: 32] = w;
      end
    end
  endtask

  initial begin : main
    fh = $fopen("vectors/tree_kat.txt", "r");
    if (!fh) begin $display("TB FAIL: cannot open vectors/tree_kat.txt"); $finish; end
    rst_n = 0; repeat (2) @(posedge clk); rst_n = 1; @(posedge clk);
    forever begin
      got = 0;
      while (!got) begin
        sc = $fscanf(fh, "%c", ch);
        if (sc <= 0) begin got = 1; eof = 1; end
        else if (ch == "#") sc = $fgets(discard, fh);
        else if (ch == "S" || ch == "L" || ch == "V" || ch == "R") got = 1;
      end
      if (eof) begin
        if (status == 2) $display("TB PASS: merkle_builder root matches tree_kat.txt");
        else $display("TB FAIL: root mismatch");
        $finish;
      end
      if (ch == "S") begin
        sc = $fscanf(fh, "%h", w);      // domain word, expected 166
        for (i = 0; i < 8; i = i + 1) begin
          sc = $fscanf(fh, "%h", w);
          startw[32*i +: 32] = w;
        end
      end else if (ch == "L") begin
        sc = $fscanf(fh, "%d", nlev);
        for (i = 0; i < nlev; i = i + 1) begin
          read_digest;
          load_en = 1; load_addr = i; @(posedge clk);
        end
        load_en = 0;
        repeat (2) @(posedge clk);
        start = 1; @(posedge clk); start = 0;
        while (!done) @(posedge clk);
      end else if (ch == "R") begin
        for (i = 0; i < 8; i = i + 1) begin
          sc = $fscanf(fh, "%h", w);
          if (root[32*i +: 32] !== w) begin
            $display("ROOT MISMATCH word %0d: got %h want %h", i, root[32*i +: 32], w);
            status = 1;
          end
        end
      end else begin                    // V lines: skip for now (levels are internal)
        sc = $fscanf(fh, "%d", nlev);
        for (i = 0; i < nlev * 8; i = i + 1) sc = $fscanf(fh, "%h", w);
      end
    end
  end
endmodule
